"use client";
import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:3001";
type Product = {
  id: string;
  title: string;
  description: string;
  price: number;
  createdAt: string;
};
export default function ProductDetailPage() {
  const params = useParams();
  const router = useRouter();
  const [product, setProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => {
    loadProduct();
  }, []);
  const loadProduct = async () => {
    try {
      const response = await fetch(`${API_URL}/api/products/${params.id}`);
      const data = await response.json();
      if (data.success) {
        setProduct(data.data);
      } else {
        setError("Produit non trouvé");
      }
    } catch (err) {
      setError("Erreur lors du chargement");
    } finally {
      setLoading(false);
    }
  };
  const handleDelete = async () => {
    if (!confirm("Voulez-vous vraiment supprimer ce produit ?")) return;
    try {
      const response = await fetch(`${API_URL}/api/products/${params.id}`, {
        method: "DELETE",
      });
      if (response.ok) {
        router.push("/dashboard/products");
      } else {
        alert("Erreur lors de la suppression");
      }
    } catch (err) {
      alert("Erreur réseau");
    }
  };
  if (loading) return <div>Chargement...</div>;
  if (error || !product) {
    return (
      <Alert variant="destructive">
        <AlertDescription>{error || "Produit non trouvé"}</AlertDescription>
      </Alert>
    );
  }
  return (
    <div className="max-w-2xl mx-auto">
      <Card>
        <CardHeader>
          <CardTitle>{product.title}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <p className="text-sm text-gray-500">Description</p>
            <p className="text-lg">{product.description}</p>
          </div>
          <div>
            <p className="text-sm text-gray-500">Prix</p>
            <p className="text-2xl font-bold">{product.price}FCFA</p>
          </div>
          <div>
            <p className="text-sm text-gray-500">Créé le</p>
            <p>{new Date(product.createdAt).toLocaleDateString("fr FR")}</p>
          </div>
          <div className="flex gap-4 pt-4">
            <Button variant="outline" onClick={() => router.back()}>
              Retour
            </Button>
            <Button variant="destructive" onClick={handleDelete}>
              Supprimer
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
